package com.menta.auth.application.port.out;

/**
 * Cross-module port to hash opaque password-reset tokens before persistence
 * — only the digest may reach MySQL, never the raw value. Mirrors
 * {@link ActivationTokenHasher}.
 */
public interface PasswordResetTokenHasher {

    /**
     * Hashes a raw reset token into the value that is persisted and looked up.
     *
     * @param rawToken URL-safe raw reset token as generated by
     *                 {@link PasswordResetTokenGenerator}.
     * @return 64-char lowercase hex digest suitable for column token_hash.
     */
    String hash(String rawToken);
}
